<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';const rows=ref<any[]>([]),page=ref(0),total=ref(0),filter=ref({tracking:'',billingStatus:'',shipmentStatus:'',from:'',to:''}),router=useRouter();const h=()=>({Authorization:`Bearer ${localStorage.getItem('token')}`});async function load(){const q=new URLSearchParams({page:String(page.value),size:'20',...(filter.value as any)});const r=await fetch(`/api/admin/billing?${q}`,{headers:h()});if(r.ok){const x=await r.json();rows.value=x.content;total.value=x.totalPages}}onMounted(load);function apply(){page.value=0;load()}</script>
<template><section class="card"><div class="card-head"><h1>Szállítmányok</h1><span>{{page+1}} / {{Math.max(total,1)}}</span></div><div class="filters"><input v-model="filter.tracking" placeholder="Master tracking"><input v-model="filter.from" type="date"><input v-model="filter.to" type="date"><select v-model="filter.shipmentStatus"><option value="">Minden státusz</option><option>CREATED</option><option>FAILED</option></select><select v-model="filter.billingStatus"><option value="">Minden számlázás</option><option>UNBILLED</option><option>INVOICED</option></select><button @click="apply">Szűrés</button></div><table><thead><tr><th>Dátum</th><th>Ügyfél</th><th>Tracking</th><th>Csomag</th><th>DHL költség</th><th>Ügyfélár</th><th>Árrés</th><th>Státusz</th></tr></thead><tbody><tr v-for="x in rows" :key="x.id" class="clickable" @click="router.push(`/admin/shipments/${x.id}`)"><td>—</td><td>{{x.company}}</td><td>{{x.masterTrackingNumber||'—'}}</td><td>{{x.packageCount}}</td><td>{{x.dhlEstimatedCost}}</td><td>{{x.customerPrice}}</td><td>{{Number(x.customerPrice||0)-Number(x.dhlEstimatedCost||0)}}</td><td>{{x.status}} / {{x.billingStatus}}</td></tr></tbody></table><p><button :disabled="page===0" @click="page--;load()">Előző</button> <button :disabled="page+1>=total" @click="page++;load()">Következő</button></p></section></template>
